    createColumn: (column: Partial<Column>) => Promise<ApiResult<Column>>,
    updateColumn: (column: Column) => Promise<ApiResult<Column>>,
    deleteColumn: (id: string, permanent?: boolean) => Promise<ApiResult<void>>,
