                                                    <div className="font-bold truncate mb-0.5">{card.title}</div>
                                                    <div className="flex items-center gap-1 text-[10px] text-gray-500">
                                                        <Hash className="h-3 w-3" />
                                                        <span className="truncate">{card.boardName}</span>
