                                                        <div className="flex items-center gap-1 text-[10px] text-gray-500 mt-0.5">
                                                            <Clock className="h-3 w-3" />
                                                            <span>{new Date(card.due_date).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
