    // Plugins
    getPlugins: async (): Promise<ApiResult<any[]>> => {
        return { success: true, data: [] };
    },
    togglePlugin: async (_id: string, _enabled: boolean): Promise<ApiResult<void>> => {
        return { success: true };
    },
    updatePluginSetting: async (_id: string, _key: string, _value: any): Promise<ApiResult<void>> => {
        return { success: true };
    }
};

export const getApi = () => {
    if (typeof window !== 'undefined' && window.api) {
        return window.api;
    }
    console.warn('Using mock API - window.api not available (not running in Electron)');
    return mockApi as unknown as Window['api'];
};
